# Some words share a leading token; combine same-direction contributions without double-counting.
def cleanlex(d):
 res={}; seen={}
 for z,v in d.items():
  idx=zids(z)[0]
  if idx not in seen or abs(v)>abs(res[seen[idx]]):
   if idx in seen: del res[seen[idx]]
   res[z]=v; seen[idx]=z
 return res
