 slots=np.argsort(build_energy)[:len(channels)]; g=cache_orig(23,'mlp.gate_proj').copy();u=cache_orig(23,'mlp.up_proj').copy();d=D24o.copy()
 for pos,(gg,uu,dd) in zip(slots,channels):g[pos]=gg;u[pos]=uu;d[:,pos]=dd
